const t="ดูแลเหมือนน้องเป็นสมาชิกในบ้านเรา",e=[{title:"คุยกันก่อนทุกครั้ง",detail:"อธิบายอาการ ทางเลือกการรักษา และค่าใช้จ่ายให้ครบก่อนเริ่ม"},{title:"ทีมสัตวแพทย์ประจำ",detail:"น้องได้พบหมอคนเดิมที่จำประวัติและนิสัยของน้องได้"},{title:"ประวัติสุขภาพออนไลน์",detail:"ดูผลเลือด วัคซีน ยาที่จ่าย และสรุปการตรวจย้อนหลังได้จากมือถือ"},{title:"ไม่ต้องรอเก้อ",detail:"จองคิวออนไลน์ เช็กคิวสดก่อนออกจากบ้าน รับแจ้งเตือนผ่าน LINE"}];export{t as a,e as c};
